/**
 * Procedural built-in sounds. Each recipe generates mono PCM samples which are encoded as a 16-bit WAV
 * file. Built-in sounds are ordinary project assets, so they need no network access and survive export.
 */
import type { BuiltInSoundDescriptor } from '../model/builtInSounds';

export const SAMPLE_RATE = 22050;

export type SynthRecipe = BuiltInSoundDescriptor['recipe'];

/** Deterministic pseudo-random generator so the generated bytes are stable across runs. */
function lcg(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 0xffffffff;
  };
}

function synthesize(recipe: SynthRecipe): Float32Array {
  const dur: Record<SynthRecipe, number> = { pop: 0.18, beep: 0.25, chime: 1.2, boing: 0.6, click: 0.04 };
  const n = Math.round(dur[recipe] * SAMPLE_RATE);
  const out = new Float32Array(n);
  const rnd = lcg(recipe.length * 7919);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SAMPLE_RATE;
    const u = t / dur[recipe];
    let v = 0;
    switch (recipe) {
      case 'pop': {
        const f = 900 * Math.pow(0.22, u);
        phase += (2 * Math.PI * f) / SAMPLE_RATE;
        v = Math.sin(phase) * Math.exp(-u * 9) * 0.9;
        break;
      }
      case 'beep': {
        phase += (2 * Math.PI * 880) / SAMPLE_RATE;
        const env = u < 0.05 ? u / 0.05 : u > 0.85 ? (1 - u) / 0.15 : 1;
        v = Math.sign(Math.sin(phase)) * 0.25 * env;
        break;
      }
      case 'chime': {
        v = (Math.sin(2 * Math.PI * 1046.5 * t) * 0.5 + Math.sin(2 * Math.PI * 1318.5 * t) * 0.35 + Math.sin(2 * Math.PI * 1568 * t) * 0.2) * Math.exp(-t * 3.2) * 0.8;
        break;
      }
      case 'boing': {
        const f = 220 + 480 * Math.exp(-u * 6) + 18 * Math.sin(2 * Math.PI * 9 * t);
        phase += (2 * Math.PI * f) / SAMPLE_RATE;
        v = Math.sin(phase) * Math.exp(-u * 4) * 0.85;
        break;
      }
      case 'click': {
        v = (rnd() * 2 - 1) * Math.exp(-u * 60) * 0.9;
        break;
      }
    }
    // Short fade-out avoids clicks at the end of the buffer.
    const fade = Math.min(1, (n - i) / (SAMPLE_RATE * 0.005));
    out[i] = Math.max(-1, Math.min(1, v * fade));
  }
  return out;
}

/** Encodes mono float samples as a 16-bit PCM WAV file. */
export function encodeWav(samples: Float32Array, sampleRate = SAMPLE_RATE): Uint8Array {
  const dataBytes = samples.length * 2;
  const buffer = new ArrayBuffer(44 + dataBytes);
  const view = new DataView(buffer);
  const writeStr = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
  };
  writeStr(0, 'RIFF');
  view.setUint32(4, 36 + dataBytes, true);
  writeStr(8, 'WAVE');
  writeStr(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true); // PCM
  view.setUint16(22, 1, true); // mono
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeStr(36, 'data');
  view.setUint32(40, dataBytes, true);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]!));
    view.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true);
  }
  return new Uint8Array(buffer);
}

/** Generates the WAV bytes for a built-in recipe. */
export function generateBuiltInWav(recipe: SynthRecipe): { bytes: Uint8Array; durationSec: number } {
  const samples = synthesize(recipe);
  return { bytes: encodeWav(samples), durationSec: samples.length / SAMPLE_RATE };
}
